import { coerceBooleanProperty } from "@angular/cdk/coercion";
import { CommonModule } from "@angular/common";
import { AfterViewInit, Component, ElementRef, Input, OnDestroy, ViewChild, ViewEncapsulation } from "@angular/core";
import { MatIconModule } from "@angular/material/icon";
import { MatTooltipModule } from "@angular/material/tooltip";
import { DscTooltipModule } from "sidsc-components/dsc-tooltip";

export type DscTagSize = 'standard' | 'small';

export type DscTagVariant = 'highlight' 
  | 'accent' 
  | 'ceu' 
  | 'danger' 
  | 'neutral' 
  | 'success' 
  | 'uva' 
  | 'information' 
  | 'warning' 
  | 'limao';

@Component({
  selector: 'dsc-tags',
  standalone: true,
  encapsulation: ViewEncapsulation.None,
  imports: [ CommonModule, MatIconModule, MatTooltipModule, DscTooltipModule ],
  templateUrl: './dsc-tags.component.html',
  styleUrls: ['./dsc-tags.component.scss']
})
export class DscTagsComponent implements AfterViewInit, OnDestroy {

  private _tagSize: DscTagSize = 'standard';

  private _tagDarkVariant: boolean = false;

  showTooltip = false;

  @Input()
  get size(): DscTagSize {
    return this._tagSize;
  }

  set size(value: DscTagSize) {
    this._tagSize = value || 'standard';
  }

  @Input() maxWidth?: string;

  @Input() icon?: string;

  @Input() label: string = 'Label';

  @Input() variant: DscTagVariant = 'highlight';

  @Input()
  get darkVariant(): boolean {
    return this._tagDarkVariant;
  }

  set darkVariant(value: boolean | string) {
    this._tagDarkVariant = coerceBooleanProperty(value);
  }

  @ViewChild('labelElement') labelEl!: ElementRef<HTMLElement>;
  private resizeObserver?: ResizeObserver;


  ngAfterViewInit() {
    const el = this.labelEl.nativeElement;
    
    this.resizeObserver = new ResizeObserver(() => this.checkTruncation(el))
    this.resizeObserver.observe(el);
  }

  ngOnDestroy(): void {
    this.resizeObserver?.disconnect();
  }

  getComputedClass(tag: DscTagVariant): string {
    if(this.darkVariant) {
      return `${tag}_dark`
    } else {
      return `${tag}_ligth`;
    }
  }

  private checkTruncation(el: HTMLElement): void {
    const isTruncated = el.offsetWidth < el.scrollWidth;
    if(this.showTooltip !== isTruncated) {
      this.showTooltip = isTruncated;
    }
  }
}
